"""Resume only the reviewed tuple-failure build, using verified local v1 inputs."""
import argparse,ast,base64,hashlib,json,os,platform,stat,sys,zlib
from pathlib import Path
OLD_ENTRY=Path('/home/jwk/agent/A_build_private_delete_daemon_v1.py')
OLD_ENTRY_SHA='7c280363779db70b8fa9b2a4aa45fd849830797ca7de933b3352ce9d144448c1'
BODY_PIN='54ed829598160de7afbaf1dd5da0b2df6fa4afd428b7c4bbcd9573a462b6eefc'
BODY_Z64=''

def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--run',action='store_true');args=parser.parse_args()
    if not args.run:
        print(json.dumps({'status':'PLAN_ONLY','scope':'resume daemon build after verified native tests; no download, test rerun, SDK, service or journal action'}));return 0
    assert sys.platform=='linux' and platform.node()=='server1' and os.getuid()==os.geteuid()==1204
    assert OLD_ENTRY.resolve(strict=True)==OLD_ENTRY
    fd=os.open(OLD_ENTRY,os.O_RDONLY|os.O_NOFOLLOW|os.O_CLOEXEC)
    with os.fdopen(fd,'rb') as stream:
        before=os.fstat(stream.fileno())
        assert stat.S_ISREG(before.st_mode) and before.st_uid==1204 and before.st_size==243866
        raw=stream.read(243867);after=os.fstat(stream.fileno())
    assert (before.st_ino,before.st_size,before.st_mtime_ns,before.st_ctime_ns)==(after.st_ino,after.st_size,after.st_mtime_ns,after.st_ctime_ns)
    assert hashlib.sha256(raw).hexdigest()==OLD_ENTRY_SHA
    names={'RELEASE','SOURCE_FILES','REPLACEMENTS','CAPTURE_WRAPPER'};values={}
    for node in ast.parse(raw).body:
        if isinstance(node,ast.Assign) and len(node.targets)==1 and isinstance(node.targets[0],ast.Name) and node.targets[0].id in names:
            assert node.targets[0].id not in values
            values[node.targets[0].id]=ast.literal_eval(node.value)
    assert set(values)==names
    body=zlib.decompress(base64.b64decode(BODY_Z64,validate=True))
    assert len(body)<32768 and hashlib.sha256(body).hexdigest()==BODY_PIN
    values.update(__name__='verified_resumed_build',__file__=__file__)
    exec(compile(body,'<verified-daemon-resume-v2>','exec'),values)
    return values['main']()

if __name__=='__main__':
    raise SystemExit(main())
